%% FIGURE 7: REFERENCE-YIELD SCALING UNDER CAPACITY- AND ENERGY-BASED TARGETS
% Reproduces Figure 7 of the paper from the sensitivity-analysis results
% generated by estimateInvestmentDecision.m.
%
% Required input files:
%   Results Paper/Results_scaling_capacity_based.mat
%   Results Paper/Results_scaling_energy_based.mat
%
% Output:
%   Results Paper/Figure_7_reference_yield_scaling.pdf

%% ------------------------------------------------------------------------
% 1. PATHS
% -------------------------------------------------------------------------

scriptPath = mfilename('fullpath');
scriptFolder = fileparts(scriptPath);
repoFolder = fileparts(scriptFolder);
resultsFolder = fullfile(repoFolder, 'Results Paper');

fileCapacityBased = fullfile(resultsFolder, 'Results_scaling_capacity_based.mat');
fileEnergyBased = fullfile(resultsFolder, 'Results_scaling_energy_based.mat');
outputFigure = fullfile(resultsFolder, 'Figure_7_reference_yield_scaling.pdf');

if ~isfile(fileCapacityBased)
    error('Capacity-based results file not found: %s', fileCapacityBased);
end

if ~isfile(fileEnergyBased)
    error('Energy-based results file not found: %s', fileEnergyBased);
end

%% ------------------------------------------------------------------------
% 2. LOAD RESULTS
% -------------------------------------------------------------------------

capacityData = load(fileCapacityBased, 'resultsScaling');
energyData = load(fileEnergyBased, 'resultsScaling');

T_capacity = capacityData.resultsScaling;
T_energy = energyData.resultsScaling;

%% ------------------------------------------------------------------------
% 3. CHECK REQUIRED VARIABLES
% -------------------------------------------------------------------------

requiredVariables = [ ...
    "scaleRefYield", ...
    "installedCapacity_GW", ...
    "subsidyExpenditure_bnEUR", ...
    "producerSurplusProbabilityBased_bnEUR", ...
    "probabilityBasedSyntheticNetBenefit_bnEUR" ...
    ];

missingCapacity = requiredVariables( ...
    ~ismember(requiredVariables, string(T_capacity.Properties.VariableNames)));

missingEnergy = requiredVariables( ...
    ~ismember(requiredVariables, string(T_energy.Properties.VariableNames)));

if ~isempty(missingCapacity)
    error('Capacity-based results are missing: %s', strjoin(missingCapacity, ', '));
end

if ~isempty(missingEnergy)
    error('Energy-based results are missing: %s', strjoin(missingEnergy, ', '));
end

%% ------------------------------------------------------------------------
% 4. EXTRACT SERIES
% -------------------------------------------------------------------------

xCapacity = T_capacity.scaleRefYield;
xEnergy = T_energy.scaleRefYield;

capacityCapacity = T_capacity.installedCapacity_GW;
capacityEnergy = T_energy.installedCapacity_GW;

supportCapacity = T_capacity.subsidyExpenditure_bnEUR;
supportEnergy = T_energy.subsidyExpenditure_bnEUR;

producerSurplusCapacity = T_capacity.producerSurplusProbabilityBased_bnEUR;
producerSurplusEnergy = T_energy.producerSurplusProbabilityBased_bnEUR;

syntheticNetBenefitCapacity = T_capacity.probabilityBasedSyntheticNetBenefit_bnEUR;
syntheticNetBenefitEnergy = T_energy.probabilityBasedSyntheticNetBenefit_bnEUR;

%% ------------------------------------------------------------------------
% 5. FIGURE SETTINGS
% -------------------------------------------------------------------------

blueEnergy = [0.00 0.45 0.74];
redCapacity = [0.85 0.20 0.20];
referenceLineColor = [0.35 0.35 0.35];

lineWidth = 2.0;
xLimits = [0 1.6];

figure( ...
    'Position', [100 100 1100 800], ...
    'Color', 'w');

layout = tiledlayout( ...
    2, 2, ...
    'TileSpacing', 'compact', ...
    'Padding', 'compact');

%% ------------------------------------------------------------------------
% 6. PANEL A: INSTALLED CAPACITY
% -------------------------------------------------------------------------

ax1 = nexttile(layout, 1);

plot(ax1, xEnergy, capacityEnergy, '-', ...
    'Color', blueEnergy, 'LineWidth', lineWidth);
hold(ax1, 'on');

plot(ax1, xCapacity, capacityCapacity, '-', ...
    'Color', redCapacity, 'LineWidth', lineWidth);

xline(ax1, 1, ':', ...
    'Color', referenceLineColor, ...
    'LineWidth', 1.2, ...
    'HandleVisibility', 'off');

grid(ax1, 'on');
box(ax1, 'on');
xlim(ax1, xLimits);

xlabel(ax1, 'Reference-yield scaling factor, s');
ylabel(ax1, 'GW');
title(ax1, 'Installed capacity');

legend(ax1, ...
    {'Energy-based target', 'Capacity-based target'}, ...
    'Location', 'best');

%% ------------------------------------------------------------------------
% 7. PANEL B: ANNUAL SUPPORT PAYMENTS
% -------------------------------------------------------------------------

ax2 = nexttile(layout, 2);

plot(ax2, xEnergy, supportEnergy, '-', ...
    'Color', blueEnergy, 'LineWidth', lineWidth);
hold(ax2, 'on');

plot(ax2, xCapacity, supportCapacity, '-', ...
    'Color', redCapacity, 'LineWidth', lineWidth);

xline(ax2, 1, ':', ...
    'Color', referenceLineColor, ...
    'LineWidth', 1.2, ...
    'HandleVisibility', 'off');

grid(ax2, 'on');
box(ax2, 'on');
xlim(ax2, xLimits);

xlabel(ax2, 'Reference-yield scaling factor, s');
ylabel(ax2, 'bn EUR/year');
title(ax2, 'Annual support payments');

%% ------------------------------------------------------------------------
% 8. PANEL C: PROBABILITY-BASED PRODUCER SURPLUS
% -------------------------------------------------------------------------

ax3 = nexttile(layout, 3);

plot(ax3, xEnergy, producerSurplusEnergy, '-', ...
    'Color', blueEnergy, 'LineWidth', lineWidth);
hold(ax3, 'on');

plot(ax3, xCapacity, producerSurplusCapacity, '-', ...
    'Color', redCapacity, 'LineWidth', lineWidth);

xline(ax3, 1, ':', ...
    'Color', referenceLineColor, ...
    'LineWidth', 1.2, ...
    'HandleVisibility', 'off');

grid(ax3, 'on');
box(ax3, 'on');
xlim(ax3, xLimits);

xlabel(ax3, 'Reference-yield scaling factor, s');
ylabel(ax3, 'bn EUR/year');
title(ax3, 'Probability-based producer surplus');

%% ------------------------------------------------------------------------
% 9. PANEL D: PROBABILITY-BASED SYNTHETIC NET BENEFIT
% -------------------------------------------------------------------------

ax4 = nexttile(layout, 4);

plot(ax4, xEnergy, syntheticNetBenefitEnergy, '-', ...
    'Color', blueEnergy, 'LineWidth', lineWidth);
hold(ax4, 'on');

plot(ax4, xCapacity, syntheticNetBenefitCapacity, '-', ...
    'Color', redCapacity, 'LineWidth', lineWidth);

xline(ax4, 1, ':', ...
    'Color', referenceLineColor, ...
    'LineWidth', 1.2, ...
    'HandleVisibility', 'off');

yline(ax4, 0, ':', ...
    'Color', referenceLineColor, ...
    'LineWidth', 1.0, ...
    'HandleVisibility', 'off');

grid(ax4, 'on');
box(ax4, 'on');
xlim(ax4, xLimits);

xlabel(ax4, 'Reference-yield scaling factor, s');
ylabel(ax4, 'bn EUR/year');
title(ax4, 'Probability-based synthetic net benefit');

%% ------------------------------------------------------------------------
% 10. COMMON FORMATTING
% -------------------------------------------------------------------------

allAxes = [ax1, ax2, ax3, ax4];

set(allAxes, ...
    'FontSize', 11, ...
    'LineWidth', 0.8);

%% ------------------------------------------------------------------------
% 11. EXPORT
% -------------------------------------------------------------------------

exportgraphics( ...
    gcf, ...
    outputFigure, ...
    'ContentType', 'vector');

fprintf('Figure 7 saved to:\n%s\n', outputFigure);
